mapper.select:
SELECT DATE_FORMAT(reservation_time, '%H:%i')
FROM Reservations
WHERE stylist_id = #{stylistId}
  AND DATE(reservation_time) = #{date}
  AND (status IN ('confirmed', 'completed')
       OR (status = 'pending' AND created_at > NOW() - INTERVAL 10 MINUTE))

mapper.update:
UPDATE Reservations
SET status = #{status}
WHERE reservation_id = #{reservationId}
  AND status = 'pending'
